function defenceItems(u, ph, opts){
  const out = [];
  // a Feel No Pain only one model has (Robotic Bodyguard: the Datasmith, not the robots) is said by that ability's own line
  for(const r of u.rules){ const m = /^feel no pain (\d\+)/i.exec(r); if(m && !u.abilities.some(ab => ab.def && ab.def.includes('Feel No Pain ' + m[1]))) out.push({ t:'Feel No Pain ' + m[1], a:'rule', v:r }); }
  for(const r of unitDetRules(u)) if(r.def && !out.some(x => x.t === r.def)) out.push({ t:r.def, a:'rule', v:r.name });   // e.g. Knights of Legend: FNP 6+
  // (who, name: the model of an attached unit the ability is on, for the datasheet's line)
  for(const ab of u.abilities) if(ab.def && !naReason(ab) && !(ph && ab.defPh && !ab.defPh.includes(ph))) out.push({ t:ab.def, a:'ability', v:abilityKey(ab), who:ab.who, name:ab.name });
  for(const s of allStratagems()) if(s.def && eligible(s).includes(u) && !(ph && !s.phases.includes(ph))) out.push({ t:s.cp + 'CP ' + s.name + ': ' + s.def, a:'strat', v:s.id });
  if(opts && opts.shields) for(const s of allStratagems()) if(s.shield && s.shield.def && matches(s.shield.protects, u) && army().units.some(x => x !== u && matches(s.shield.by, x)) && !(ph && !s.phases.includes(ph)))
    out.push({ t:s.cp + 'CP ' + s.name + ': ' + s.shield.def, a:'strat', v:s.id });
  // and on the datasheet what another unit of the list gives this one when it is attacked (guard: Emanatus Forcefield,
  // Shroudpsalm, Necromechanic), as its attack auras show under its weapons; the source's name opens that unit
  if(opts && opts.shields) for(const src of army().units) for(const g of src.guard || []) if(src !== u && matches(g.needs, u))
    out.push({ t:g.when + ': ' + g.note, a:'unit', v:src.id, guard:g });
  if(u.rules.includes('Waaagh!')) out.push({ t:'Riled up: 5+ INV', a:'rule', v:'Waaagh!', riled:true });
  return out;
}

function screenPregame(){
  const a = army(), f = faction(), units = a.units;
  const row = (k, v) => v ? '<div class="pgr"><span class="pgk">' + k + '</span><span class="pgv">' + v + '</span></div>' : '';
  const sec = (title, body) => body ? '<div class="sec-h"><h2>' + title + '</h2></div><div class="pg">' + body + '</div>' : '';
  // the same ability on several units is one line: "Singular Purpose · Assimilator (280), Norn Emissary ×2"
  const group = list => { const m = new Map(); for(const [u, ab] of list){ const k = ab.name + '|' + ab.text; if(!m.has(k)) m.set(k, { ab, units:[] }); m.get(k).units.push(u); } return [...m.values()]; };
  const abLine = g => linkTo('ability', abilityKey(g.ab), g.ab.name) + ' <span class="from">· ' + esc(unitNames(g.units)) + '</span>';
  const rulesOf = units.length ? f.armyRules.filter(r => !inertRule(r.name)).map(r => ({ r, src:f.name + ' army rule' }))
    .concat(detachments().filter(d => d.rule).map(d => ({ r:d.rule, src:d.name }))) : [];
  const ruleLine = x => linkTo('rule', x.r.name, x.r.name) + ' <span class="from">· ' + esc(x.src) + '</span>';
  const nameLink = u => linkTo('unit', u.id, u.short || u.name);   // without its enhancement: the line says it
  // a unit's short name, or its full one when another unit of the list has that short name too (Big Mek Dakkarig, Big Mek in Mega Armour)
  const ownName = u => u.short && units.some(x => x !== u && (x.short || x.name) === u.short && x.name !== u.name) ? u.name : u.short || u.name;
  const allAbs = units.flatMap(u => u.abilities.filter(ab => !naReason(ab)).map(ab => [u, ab]));
  // Deep Strike (24.09) and Scouts (24.31) work only if every model in the unit has them; u.partialRules names
  // the rules only some models of an attached unit have (Slaughterbound's Scouts 6": its Exalted Eightbound have none)
  const everyModel = (u, test) => unitRules(u).some(test) && !Object.keys(u.partialRules || {}).some(test);
  // rules resolved before Declare Battle Formations (Code Chivalric: end of the Read Mission Objectives step)
  const early = rulesOf.filter(x => /read mission objectives/i.test(x.r.text));

  // your list
  const warlord = units.filter(u => u.warlord);
  const enh = units.flatMap(u => [u.enhancement, u.upgrade].filter(Boolean).map(n => { const d = detachments().find(x => (x.enhancements || []).some(e => e.name === n)), e = d && d.enhancements.find(x => x.name === n);
    return (d ? linkTo('enh', d.id + '|' + n, n) : esc(n)) + (n === u.upgrade ? ' <span class="from">(upgrade)</span>' : '') + (e && e.pts ? ' <span class="from">' + e.pts + ' pts</span>' : '') + ' on ' + (n === u.enhancement && u.enhOn ? linkTo('unit', u.id, u.enhOn) : n === u.upgrade && u.leads ? linkTo('unit', u.id, u.leads) : linkTo('unit', u.id, ownName(u) + unitNo(u))); }));
  const led = units.filter(u => u.leads).flatMap(u => charsOf(u).map((c, i) => (i ? linkTo('unit', u.id, c.name) : nameLink(u)) + (c.support ? ' supports ' : ' leads ') + esc(u.leads) + (u.copies > 1 ? ' <span class="from">×' + u.copies + ' units</span>' : '')));
  let h = sec('Your list',
    row('Warlord', warlord.map(u => u.warlordOn ? linkTo('unit', u.id, u.warlordOn) + ' <span class="from">(' + esc(unitLabel(u)) + ')</span>' : unitLink(u)).join(', ')) +
    row('Enhance&shy;ments', enh.join('<br>')) +
    row('Attached', led.join('<br>')) +
    row('Detach&shy;ments', detachments().map(d => (d.rule ? linkTo('rule', d.rule.name, d.name) : esc(d.name)) + (d.dp ? ' <span class="from">(' + d.dp + ' DP)</span>' : '')).join(', ') + (a.disposition ? '<br><span class="from">Disposition:</span> ' + esc(a.disposition) : '')) +
    // the other selections New Recruit prints under the army name, as printed; one that only names the parts of an army
    // rule ("Code Chivalric: Deed, Quality", each part's table rows) is no pick: that rule is under Army rules
    Object.entries(a.config || {}).filter(([k, v]) => !ruleParts(f, k, v)).map(([k, v]) => row(esc(k), esc(v))).join('') +
    row('Points', esc(a.pointsUsed + ' / ' + a.points + ' · ' + a.battleSize)));
  // the army rules and the detachment rules, folded: each opens to its text (the detachment's row as on the Rules tab)
  const detRows = detachments().filter(d => d.rule).map(d => ruleRow(d.rule.name, metaLine(esc(d.name), d.rule.ph ? esc(shortWhen(d.rule)) : ''),
    (d.rule.note ? '<p class="note it">' + esc(d.rule.note) + '</p>' : '') + textWithTable(d.rule) + usedBy('Applies to', units.filter(u => matches(d.rule.needs, u))))).join('');
  h += f.armyRules.length || detRows ? '<div class="sec-h"><h2>' + (detRows ? 'Army and detachment rules' : 'Army rules') + '</h2></div><div class="abl">' + armyRuleRows(f) + detRows + '</div>' : '';

  const earlyAbs = group(allAbs.filter(([u, ab]) => /read mission objectives/i.test(ab.text)));
  h += sec('Read Mission Objectives step', row('Rules', early.map(ruleLine).join('<br>')) + row('Abilities', earlyAbs.map(abLine).join('<br>')));

  // declare battle formations: reserves and transports
  const ds = units.filter(u => everyModel(u, r => ruleKey(r) === 'Deep Strike'));
  const dsPts = ds.reduce((t, u) => t + (u.pts || 0) * (u.copies || 1), 0);
  const transports = units.filter(u => hasKw(u, 'Transport')).map(u => { const ab = u.abilities.find(x => /transport capacity/i.test(x.text)); return unitLink(u) + (ab ? ': <span class="from">' + inline(ab.text.replace(/(^|\n)\*([^*\n][^\n]*[^*\n])\*(?=\n|$)/g, '$1$2').replace(/\n(- )?/g, ' ')) + '</span>' : ''); });
  h += sec('Declare battle formations',
    row(linkTo('rule', 'Deep Strike', 'Deep Strike'), ds.map(u => (u.leads ? linkTo('unit', u.id, unitLabel(u)) : unitLink(u)) + ' <span class="from">' + u.pts + ' pts' + (u.copies > 1 ? ' each, ×' + u.copies : '') + '</span>').join('<br>') + (ds.length > 1 ? '<br><span class="from">All of them: ' + dsPts + ' pts</span>' : '')) +
    row('Transports', transports.join('<br>')));

  // deployment and pre-battle abilities
  const scouts = units.filter(u => everyModel(u, r => /^scouts|^infiltrators/i.test(r)));
  const scoutRules = u => unitRules(u).filter(r => /^scouts|^infiltrators/i.test(r));
  const scoutKeys = [...new Set(scouts.flatMap(u => scoutRules(u).map(ruleKey)))].sort((x, y) => (x === 'Scouts' ? 0 : 1) - (y === 'Scouts' ? 0 : 1));
  const pre = group(allAbs.filter(([u, ab]) => PREGAME_RE.test(ab.text) && !/start of the first battle round|read mission objectives/i.test(ab.text)));
  h += sec('Deployment and pre-battle abilities',
    row(scoutKeys.map(k => linkTo('rule', k, k)).join(' and '), scouts.map(u => unitLink(u) + ' <span class="from">' + scoutRules(u).map(r => linkTo('rule', r, r)).join(', ') + '</span>').join('<br>')) +
    row('Abilities', pre.map(abLine).join('<br>')) +
    row('Rules', rulesOf.filter(x => PREGAME_RE.test(x.r.text) && !early.includes(x)).map(ruleLine).join('<br>')));

  // decided at the start of the battle (before the first battle round: Aegis Protocol, Code Chivalric's Deed 1–2, a row of its
  // table), of the first battle round or of every battle round
  const START = /\bstart of the battle\b(?! round)/i;
  const atStart = rulesOf.flatMap(x => { const rows = START.test(x.r.text) ? [] : (x.r.table || []).filter(([, t]) => START.test(t)).map(([l]) => String(l).split(' · ')[0]);
    return START.test(x.r.text) || rows.length ? [linkTo('rule', x.r.name, x.r.name) + ' <span class="from">' + (rows.length ? '(' + esc(rows.join(', ')) + ') ' : '') + '· ' + esc(x.src) + '</span>'] : []; })
    .concat(group(allAbs.filter(([u, ab]) => START.test(ab.text))).map(abLine));
  const first = group(allAbs.filter(([u, ab]) => /start of the first battle round/i.test(ab.text)));
  const round = rulesOf.filter(x => /start of (the|each|every) battle round/i.test(x.r.text)).map(ruleLine)
    .concat(group(allAbs.filter(([u, ab]) => /start of (the|each|every) battle round/i.test(ab.text) && !/start of the first battle round/i.test(ab.text))).map(abLine));
  const firstRules = rulesOf.filter(x => /start of the first battle round/i.test(x.r.text)).map(ruleLine);
  h += sec('Start of the battle and the battle rounds', row('Start of the battle', atStart.join('<br>')) + row('First round', firstRules.concat(first.map(abLine)).join('<br>')) + row('Every round', round.join('<br>')));

  // uses per battle: the resources you spend, ticked off until New game
  // a rule that gives units a "(Once per battle, per unit)" ability (Higher Imperatives) is ticked on those units, not here
  const ruleOnce = r => perBattle(r) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '');
  const onceRules = f.armyRules.filter(r => !inertRule(r.name) && ruleOnce(r)).map(r => ({ r, src:f.name + ' army rule' }))
    .concat(detachments().filter(d => d.rule && ruleOnce(d.rule)).map(d => ({ r:d.rule, src:d.name })));
  const tl = (boxes, text) => '<div class="tl">' + boxes + '<span>' + text + '</span></div>';
  const ruleTicks = x => { const r = x.r, pb = perBattle(r, true);
    // "You can only select each of these abilities once per battle" (Kindred Sorcery): a box per option
    if(/\beach of these [a-z ]+ once per battle/i.test(r.text) && r.table) return '<div class="tl"><span>' + ruleLine(x) + ':</span></div>' + r.table.map(o => tl(ticks('r:' + r.name + ':' + o[0], 1, '', o[0]), esc(o[0]))).join('');
    return tl(ticks('r:' + r.name, pb.n, '', r.name), ruleLine(x)); };
  const onceAbs = group(allAbs.filter(([u, ab]) => perBattle(ab)));
  const abTicks = g => perBattle(g.ab).army ? tl(abilityTicks(g.ab, g.units[0]), abLine(g) + ' <span class="tg once">per army</span>')
    : g.units.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) => tl(ticks(copyKey(g.ab, u, i), perBattle(g.ab).n, '', g.ab.name + (u.copies > 1 ? ', Unit ' + (i + 1) : '')),
        linkTo('ability', abilityKey(g.ab), g.ab.name) + ' · ' + linkTo('unit', u.id, unitLabel(u)) + (u.copies > 1 ? ' <span class="from">· Unit ' + (i + 1) + '</span>' : '')))).join('');
  const onceStrats = allStratagems().filter(s => eligible(s).length && perBattle(s));
  h += sec('Uses per battle',
    row('Rules', onceRules.map(ruleTicks).join('')) +
    row('Abilities', onceAbs.map(abTicks).join('')) +
    row('Strata&shy;gems', onceStrats.map(s => tl(ticks('s:' + s.id, perBattle(s, true).n, '', s.name), linkTo('strat', s.id, s.cp + 'CP ' + s.name))).join('')));
  if(onceRules.length || onceAbs.length || onceStrats.length) h = h.replace(/(<div class="sec-h"><h2>Uses per battle<\/h2>)/, '$1<button class="textbtn" data-newgame>New game</button>');
  return h + '<p class="note">Gathered from this list’s datasheets and rules; each line opens the full text.</p>';
}

function newGame(a){
  const keys = [gameKey(a), 'wh-used-' + a.id];
  const was = keys.map(k => [k, store.get(k, null)]);
  store.set(keys[0], null); for(const k of keys.slice(1)) store.set(k, []);
  return () => { for(const [k, v] of was) store.set(k, v); };
}

function gRows(L, items, picked, pickOf){
  const now = e => { const n = pickOf ? pickOf(e) : ''; return n ? '<span class="gpn">Picked: ' + esc(n) + '</span>' : ''; };
  return items.map(e => {
    if(e.kind === 'strat'){ const s = e.s, pb = perBattle(s);
      return '<div class="gr gs' + (e.usable ? '' : ' none') + '"><span class="cp' + (s.cp >= 2 ? ' hot' : '') + '">' + esc(s.cp) + '<small>CP</small></span><span class="grb">' + linkTo('strat', s.id, s.name) +
        (s.gist ? '<span class="sg">' + esc(s.gist) + '</span>' : '') + (e.usable ? '' : '<span class="from">' + esc(inArmy(L, () => usersLine(s))) + '</span>') + (pb ? ticks('s:' + s.id, pb.n, '', s.name) : '') + '</span></div>'; }
    if(e.kind === 'rule'){ const r = e.x, pb = perBattle(r, true) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '');
      // the Overview's boxes: "You can only select each of these abilities once per battle" (Kindred Sorcery) has one per ability
      const each = pb && /\beach of these [a-z ]+ once per battle/i.test(r.text) && r.table;
      const boxes = !pb ? '' : each ? r.table.map(o => ticks('r:' + r.name + ':' + o[0], 1, o[0], o[0])).join('') : ticks('r:' + r.name, pb.n, '', r.name);
      return '<div class="gr"><span class="grb">' + linkTo('rule', e.name, e.name) + ' <span class="from">· ' + esc(e.src) + '</span>' + now(e) + (boxes ? '<span class="gtk">' + boxes + '</span>' : '') + '</span></div>'; }
    const p = picked ? picked(e.ab, e.units) : null, pb = perBattle(e.ab) && !naReason(e.ab);
    const who = e.ab.who && (p !== null || !e.src.includes(e.ab.who.replace(/: pick one$/, ''))) ? e.ab.who.replace(/: pick one$/, '') : '';
    const boxes = !pb ? '' : perBattle(e.ab).army ? abilityTicks(e.ab, e.units[0]) : e.units.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) =>
      ticks(copyKey(e.ab, u, i), perBattle(e.ab).n, e.units.length > 1 || (u.copies || 1) > 1 ? shortName(u) + ((u.copies || 1) > 1 ? ' ' + (i + 1) : '') : '', e.ab.name))).join('');
    return '<div class="gr' + (p === false ? ' none' : '') + '"><span class="grb">' + linkTo('ability', e.key, e.ab.name) + ' <span class="from">· ' + esc(e.src) + '</span>' +
      (who ? ' <span class="tg m">' + esc(who) + (p === true ? ': picked' : p === false ? ': not picked' : '') + '</span>' : '') + now(e) + (boxes ? '<span class="gtk">' + boxes + '</span>' : '') + '</span></div>';
  }).join('');
}

function gameCpRules(L){
  const out = inArmy(L, () => {
    const out = [], f = faction(), line = t => String(t || '').split('\n').filter(l => !/^\*/.test(l.trim())).map(l => (G_CP.exec(l) || [])[0]).find(Boolean);
    for(const r of f.armyRules){ const s = !inertRule(r.name) && line(r.text); if(s) out.push({ t:'rule', v:r.name, name:r.name, src:f.name + ' army rule', s:s.trim() }); }
    for(const d of detachments()){ const s = d.rule && line(d.rule.text); if(s) out.push({ t:'rule', v:d.rule.name, name:d.rule.name, src:d.name, s:s.trim() }); }
    const by = new Map();
    for(const u of army().units) for(const ab of u.abilities){ const s = !naReason(ab) && line(ab.text); if(!s) continue;
      const k = abilityKey(ab); if(!by.has(k)) by.set(k, { t:'ability', v:k, name:ab.name, s:s.trim(), units:[] }); by.get(k).units.push(u); }
    for(const e of by.values()) out.push(Object.assign(e, { src:labelList(e.units) }));
    return out;
  });
  return out.map(e => Object.assign(e, { link:linkTo(e.t, e.v, e.name) }));
}

function gPregameHtml(a, g, me){
  const lists = [[a, 'This list']];
  const unitsLine = (L, us, extra) => us.map(u => linkTo('unit', u.id, gUnitName(u)) + (u.copies > 1 ? ' <span class="from">×' + u.copies + '</span>' : '') + (extra ? ' <span class="from">' + esc(extra(u)) + '</span>' : '')).join(', ');
  const per = (fn) => lists.map(([L, label]) => { const t = fn(L); return t ? '<p class="gpl"><span class="il">' + label + '</span>' + t + '</p>' : ''; }).join('');
  const add = {
    7:() => { const line = D.rules['Strategic Reserves'].split('\n').find(l => /50% of your points limit/.test(l));
      return gq(esc('20.01 Placing Units in Strategic Reserves'), line) + per(L => { const ds = gEvery(L, r => inArmy(L, () => ruleKey(r)) === 'Deep Strike');
        const pts = ds.reduce((t, u) => t + (u.pts || 0) * (u.copies || 1), 0);
        return gNote(esc(L.name) + ': points limit ' + L.points + ' pts (' + esc(L.battleSize) + '); 50% of it is ' + Math.floor(L.points / 2) + ' pts.') +
          (ds.length ? '<span class="gpu">Deep Strike: ' + unitsLine(L, ds, u => u.pts + ' pts' + (u.copies > 1 ? ' each, ×' + u.copies : '')) + (ds.length > 1 ? ' <span class="from">(' + pts + ' pts)</span>' : '') + '</span>' : ''); }); },
    8:() => per(L => { const tt = L.units.filter(u => hasKw(u, 'Titanic')), inf = gEvery(L, r => /^infiltrators/i.test(r));
      return [tt.length ? '<span class="gpu">TITANIC: ' + unitsLine(L, tt) + '</span>' : '', inf.length ? '<span class="gpu">' + linkTo('rule', 'Infiltrators', 'Infiltrators') + ': ' + unitsLine(L, inf) + '</span>' : ''].join(''); }),
    10:() => '<div class="chips" role="group" aria-label="Who takes the first turn"><span class="gcg">First turn</span>' + [me, gOther(me)].map(s => { const on = g.first === s;
      return '<button class="chip' + (on ? ' on' : '') + '" data-gset="first|' + s + '" aria-pressed="' + on + '">' + (s === me ? esc(a.name) : 'Opponent') + '</button>'; }).join('') + '</div>',
    11:() => per(L => { const sc = gEvery(L, r => /^scouts/i.test(r));
      return sc.length ? '<span class="gpu">' + linkTo('rule', 'Scouts', 'Scouts') + ': ' + unitsLine(L, sc, u => inArmy(L, () => unitRules(u).filter(r => /^scouts/i.test(r)).join(', '))) + '</span>' : ''; })
  };
  const titanic = lists.some(([L]) => L.units.some(u => hasKw(u, 'Titanic'))), infil = lists.some(([L]) => gEvery(L, r => /^infiltrators/i.test(r)).length);
  const scouts = lists.some(([L]) => gEvery(L, r => /^scouts/i.test(r)).length);
  const sub = { 7:'Strategic reserves', 8:[titanic ? 'TITANIC' : '', infil ? 'Infiltrators' : ''].filter(Boolean).join(', '), 10:'Who goes first', 11:scouts ? 'Scouts' : '' };
  return '<p class="note">Warhammer Event Mission Sequence · GW Warhammer Event Companion 1.3</p><div class="abl">' + D.game.sequence.map(([n, title, text]) => {
    const more = add[n] ? add[n]() : '';
    const body = n === 8 && titanic ? rt(text.split('\n').map(l => /\bTITANIC\b/.test(l) ? '- ' + l : l).join('\n')) : rt(text);
    return '<details class="ab rr gseq"><summary><span class="an"><b><span class="gn">' + n + '</span> ' + esc(title) + '</b>' + (sub[n] ? '<span class="rs">' + esc(sub[n]) + '</span>' : '') + '</span>' + chev + '</summary><div class="body">' + body + more + '</div></details>';
  }).join('') + '</div>';
}

function gChoiceHtml(c, g, side){
  const P = gcPick(c, g, side), v = P.v, R = gcRound(c, g, side);
  const pick = (grp, opt) => esc(JSON.stringify([c.key, R, grp, opt || '']));
  const used = c.once && !c.unit ? new Set(c.groups.flatMap(gr => gr.opts.filter(o => usedSet().has('r:' + c.name + ':' + o.row + '#0')).map(o => o.name))) : new Set();
  const lasts = c.lasts === 'battle' ? 'For the battle' : c.lasts === 'kept' ? 'Until another is picked' : c.lasts === 'command' ? 'Until the start of your next Command phase' : 'Battle round ' + g.round;
  let h = '<div class="gc"><div class="gch">' + linkTo(c.link[0], c.link[1], c.name) + ' <span class="from">· ' + esc(c.src) + '</span></div>' +
    '<p class="gcw">' + esc(c.when) + (c.when ? ' · ' : '') + '<b>' + esc(lasts) + '</b>' + (P.since === 'start' ? ' <span class="from">(from the start of the battle)</span>' : P.since ? ' <span class="from">(picked in battle round ' + P.since + ')</span>' : '') + '</p>' +
    // a step the Event Companion's mission sequence (Before the battle) does not have, named as the rule names it
    ((m => m && !D.game.sequence.some(([, t]) => norm(t) === norm(m[1])) ? gNote('the Event Companion’s mission sequence (Before the battle, below) has no step called ' + esc(m[1]) + '.') : '')(/\bthe ([A-Z][a-z]+(?: [A-Z][a-z]+)+) step\b/.exec(c.when)));
  for(const gr of c.groups){
    const on = gcNames(v[gr.name]);
    h += '<div class="chips" role="group"' + (gr.name ? ' aria-label="' + esc(gr.name) + '"' : '') + '>' + (gr.name ? '<span class="gcg">' + esc(gr.name) + '</span>' : '') +
      gr.opts.map(o => { const sel = on.includes(o.name), u = !sel && used.has(o.name);
        return '<button class="chip' + (sel ? ' on' : '') + (u ? ' used' : '') + '" data-gpick="' + pick(gr.name, o.name) + '" aria-pressed="' + sel + '">' + esc(o.name) + (u ? '<span class="u">used</span>' : '') + '</button>'; }).join('') +
      (c.rolled ? '<button class="chip rl' + (v['rolled:' + gr.name] ? ' on' : '') + '" data-gpick="' + pick('rolled:' + gr.name) + '" aria-pressed="' + !!v['rolled:' + gr.name] + '">Rolled</button>' : '') + '</div>';
    for(const o of gr.opts.filter(o => on.includes(o.name))){
      h += '<div class="gq gpk"><span class="gqs">' + esc((gr.name ? gr.name + ' ' : '') + o.name + (o.title ? ' · ' + o.title : '')) + '</span>' + rt(o.text) + '</div>';
    }
  }
  if(c.state) h += '<div class="chips"><button class="chip' + (v['state'] ? ' on' : '') + '" data-gpick="' + pick('state') + '" aria-pressed="' + !!v['state'] + '">' + esc(c.state) + '</button></div>';
  // the picks of the other battle rounds of this game
  if(c.lasts !== 'battle'){
    const past = Object.keys(P.all).filter(r => r !== R && +r >= 1).sort((x, y) => x - y).map(r => [r, c.groups.flatMap(gr => gcNames((P.all[r] || {})[gr.name]))]).filter(([, n]) => n.length);
    if(past.length) h += '<p class="gcp">' + past.map(([r, n]) => 'Round ' + r + ': ' + esc(n.join(', '))).join(' · ') + '</p>';
  }
  return h + '</div>';
}

function gamePick(a, spec){
  let k, R, grp, opt;
  try { [k, R, grp, opt] = JSON.parse(spec); } catch(e){ return; }
  const g = gameOf(a), side = 'mine', c = gameChoices(a).find(x => x.key === k);
  if(!c) return;
  const P = g.picks[side] = isObj(g.picks[side]) ? g.picks[side] : {}, all = P[k] = isObj(P[k]) ? P[k] : {}, v = all[R] = isObj(all[R]) ? all[R] : {};
  if(/^rolled:|^state$/.test(grp)){ const x = opt || true; if(v[grp] === x) delete v[grp]; else v[grp] = x; }
  else {
    const was = gcNames(v[grp]), next = was.includes(opt) ? was.filter(x => x !== opt) : c.max > 1 ? was.concat(opt).slice(-c.max) : [opt];
    if(next.length) v[grp] = c.max > 1 ? next : next[0]; else delete v[grp];
    const gr = c.groups.find(x => x.name === grp);
    if(c.once && gr){ const used = usedSet();
      for(const o of gr.opts){ const tk = 'r:' + c.name + ':' + o.row + '#0', other = Object.entries(all).some(([r, x]) => r !== R && gcNames((x || {})[grp]).includes(o.name));
        if(next.includes(o.name)) used.add(tk); else if(was.includes(o.name) && !other) used.delete(tk); }
      store.set(usedKey(), [...used]); }
  }
  if(!Object.keys(v).length) delete all[R];
  gameSave(a, g);
}
